def check_m47():
    for ak in range(2, 49):
        num = 336 * (ak - 1)
        den = 336 - ak
        if num % den == 0:
            ak_prime = 1 + num // den
            # The set of integers is {2, 3, ..., 48} \ {ak} U {ak_prime}
            # We need these to be distinct and positive.
            # ak_prime must not be in {2, ..., 48} \ {ak}
            if ak_prime != ak and (ak_prime < 2 or ak_prime > 48):
                return True, ak, ak_prime
    return False, None, None

print(check_m47())

