def check_m48():
    for aj in range(2, 50):
        num = 335 * aj
        den = 343 - 8 * aj
        if den != 0 and num % den == 0:
            a48 = num // den
            if a48 > 0 and a48 != aj and (a48 < 2 or a48 > 49 or a48 == aj): # Wait, this condition is slightly wrong
